$ErrorActionPreference='Continue';$dest=Join-Path $env:TEMP ('AutoRunner-ControlPlane-'+[Guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $dest|Out-Null;Push-Location (Join-Path $PSScriptRoot '..\docker');try{docker version *> (Join-Path $dest docker-version.txt);docker compose version *> (Join-Path $dest compose-version.txt);docker compose ps -a *> (Join-Path $dest compose-ps.txt);docker compose logs --no-color --tail=1000 *> (Join-Path $dest compose-logs.txt);docker compose config *> (Join-Path $dest compose-config.txt)}finally{Pop-Location};$zip=Join-Path ([Environment]::GetFolderPath('Desktop')) ('AutoRunner-ControlPlane-Diagnostico-'+(Get-Date -Format yyyyMMdd_HHmmss)+'.zip');Compress-Archive -Path (Join-Path $dest '*') -DestinationPath $zip -Force;Remove-Item $dest -Recurse -Force;Write-Host $zip
